/** Search for manga with core fields */
export declare const SEARCH_MANGA = "\nquery ($search: String, $page: Int, $perPage: Int) {\n  Page(page: $page, perPage: $perPage) {\n    pageInfo {\n      total\n      currentPage\n      lastPage\n      hasNextPage\n    }\n    media(search: $search, type: MANGA, sort: SEARCH_MATCH) {\n      id\n      idMal\n      title {\n        romaji\n        english\n        native\n      }\n      synonyms\n      description(asHtml: false)\n      format\n      status\n      startDate { year month day }\n      chapters\n      volumes\n      coverImage {\n        extraLarge\n        large\n        medium\n        color\n      }\n      bannerImage\n      averageScore\n      popularity\n      countryOfOrigin\n      isAdult\n      genres\n    }\n  }\n}\n";
/** Get comprehensive manga details */
